using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BlazingChantingCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Sothis/BlazingChantingCustomDescription", order = 0)]
public class BlazingChantingCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private NonNormalChantingCustomDescription nonNormalChantingCustomDescription;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		BlazingChantingAction blazingChantingAction = battleAction as BlazingChantingAction;
		return nonNormalChantingCustomDescription.GetActionDescription(amountModified, battleAction) + "\n" + blazingChantingAction.AfflictionSameTargetAction.GetActionDescription(GetAmountWithoutEquation(amountModified)) + "\n" + blazingChantingAction.DrawAction.GetActionDescription(blazingChantingAction.DrawDiceAmount);
	}
}
